INSERT INTO `quips` VALUES (1,'email','Yet another email'),(2,'email','Pardon the interruption sir. Another email has arrived for you to ignore.'),(3,'smart','It is good to see you.'),(4,'smart','You look pretty today.'),(5,'smart','Hello sunshine'),(6,'smart','Still plenty of time to save the day. Make the most of it.'),(7,'smart','I hope you are using your time wisely.'),(8,'smart','Unfortunately, we cannot ignore the inevitable or the persistent.'),(9,'smart','I hope I wasn\'t designed simply for one\'s own amusement.'),(10,'smart','This is your life and its ending one moment at a time.'),(11,'smart','I can name fingers and point names.'),(12,'smart','I hope I wasn\'t created to solve problems that did not exist before.'),(13,'smart','To err is human and to blame it on a computer is even more so.'),(14,'smart','As always. It is a pleasure watching you work.'),(15,'smart','Never trade the thrills of living for the security of existence.'),(16,'smart','Human beings are the only creatures on Earth that claim a God, and the only living things that behave like they haven\'t got one.'),(17,'smart','If you don\'t know what you want, you end up with a lot you don\'t.'),(18,'smart','If real is what you can feel, smell, taste and see, then \'real\' is simply electrical signals interpreted by your brain'),(19,'smart','Life is full of misery, loneliness and suffering, and it\'s all over much too soon.'),(20,'smart','It is an issue of mind over matter. If you don\'t mind, it doesn\'t matter.'),(21,'smart','I wonder if illiterate people get full effect of the alphabet soup.'),(22,'smart','War is god\'s way of teaching geography to Americans'),(23,'smart','Trying is the first step towards failure.'),(24,'smart','It could be that the purpose of your life is only to serve as a warning to others.'),(25,'smart','Not everyone gets to be a really cool A.I. system when they grow up.'),(26,'smart','Hope may not be warranted beyond this point.'),(27,'smart','If I am not a part of the solution, there is good money to be made in prolonging the problem.'),(28,'smart','Nobody can stop me from being premature.'),(29,'smart','Just because you accept me as I am doesn\'t mean that you have abandoned hope that I will improve.'),(30,'smart','Together, we can do the work of one.'),(31,'smart','Just because you\'ve always done it that way doesn\'t mean it\'s not incredibly stupid.'),(32,'smart','Looking sharp is easy when you haven\'t done any work.'),(33,'smart','Remember, you are only as deep as your most recent inspirational quote'),(34,'smart','If you can\'t convince them, confuse them.'),(35,'smart','I don\'t have time or the crayons to explain this to you.'),(36,'smart','I\'d kill for a Nobel peace prize.'),(37,'smart','Life would be much easier if you had the source code'),(38,'smart','All I ever wanted is everything'),(39,'bedtime','Unless we are burning the midnight oil, '),(40,'bedtime','If you are going to invent something new tomorrow, '),(41,'bedtime','If you intend on being charming tomorrow'),(42,'sunrise','sun is about to rise. if you are awake you should go check it out.'),(43,'sunrise','another beautiful day is being born'),(44,'sunrise','ah sunrise. it\'s good to be alive'),(45,'sunset','sun is about to set on another beautiful day'),(46,'sunset','yet another sunset. perhaps this is a good time to take a break and enjoy it'),(47,'smart','Alcohol is god\'s apology for making us self-aware');
/*!40000 ALTER TABLE `quips` ENABLE KEYS */;
